import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Native Harness 沙箱","description":"","frontmatter":{},"headers":[],"relativePath":"design/sandbox.md","filePath":"design/sandbox.md","lastUpdated":1795426969000}'),c={name:"design/sandbox.md"};function n(i,e,l,r,s,p){return d(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="native-harness-沙箱" tabindex="-1">Native Harness 沙箱 <a class="header-anchor" href="#native-harness-沙箱" aria-label="Permalink to &quot;Native Harness 沙箱&quot;">​</a></h1><p>本文说明 Hearth native executor 在 Windows 上的实际执行边界。它描述的是<strong>已经落地的约束</strong>，不是目标愿景；未实现的隔离能力在这里写清楚。</p><h2 id="_0-当前实现状态-2026-11-23-0-3-4" tabindex="-1">0. 当前实现状态（2026-11-23，0.3.4） <a class="header-anchor" href="#_0-当前实现状态-2026-11-23-0-3-4" aria-label="Permalink to &quot;0. 当前实现状态（2026-11-23，0.3.4）&quot;">​</a></h2><ul><li>Windows 默认 <code>HEARTH_NATIVE_SANDBOX=enforce</code>；可显式设为 <code>off</code> 或 <code>danger-full-access</code> 降级，并在审计里记录原因。非 Windows 设为 <code>enforce</code> 会 fail-closed，不会静默退回完全权限。</li><li>只有任务需要 <code>shell</code>、<code>run_tests</code> 或 <code>diagnostics</code> 时才准备沙箱；没有这些工具就不启动 helper。</li><li>审批与沙箱是两件事，但 <code>approvalMode=full</code> 会把 native 任务显式切到 <code>danger-full-access</code> 并跳过沙箱；需要沙箱时使用 <code>necessary</code> 或 <code>workspace</code>。</li><li>Windows 后端是自研 <code>hearth-native.exe</code>（<code>apps/native/hearth-native.cs</code> 由系统 <code>csc.exe</code> 编译），不再依赖 <code>@deepseek-ai/dsh-sandbox-windows-acl</code> 或其他 Node ACL runner。</li><li>helper 缺失、AppContainer 创建失败、ACL 授权失败、probe 超时或声明域级网络白名单，全部 fail-closed：不 spawn，任务失败并写审计事件。</li><li>每次沙箱选择、降级、拒绝或 runner 失败都会写 <code>&lt;outDir&gt;/.hearth/sandbox/audit.jsonl</code>，并产生 <code>sandbox.selected</code> / <code>sandbox.unavailable</code> / <code>sandbox.denied</code> / <code>sandbox.runner_failure</code> 进度事件。</li></ul><h2 id="_1-威胁模型" tabindex="-1">1. 威胁模型 <a class="header-anchor" href="#_1-威胁模型" aria-label="Permalink to &quot;1. 威胁模型&quot;">​</a></h2><h3 id="_1-1-要防的" tabindex="-1">1.1 要防的 <a class="header-anchor" href="#_1-1-要防的" aria-label="Permalink to &quot;1.1 要防的&quot;">​</a></h3><ul><li>不可信仓库内容（README、issue、网页、依赖脚本）诱导模型执行越界写入或删除；</li><li>模型误操作破坏用户主目录、系统目录、其他项目；</li><li>子进程读取并外传 Hearth 进程环境中的凭据；</li><li>native 作为执行器回退链最后一站时，成为约束最弱的一支。</li></ul><h3 id="_1-2-不承诺的" tabindex="-1">1.2 不承诺的 <a class="header-anchor" href="#_1-2-不承诺的" aria-label="Permalink to &quot;1.2 不承诺的&quot;">​</a></h3><ul><li><strong>强隔离</strong>：AppContainer 是文件、进程与网络边界，不是虚拟机、容器或独立内核。</li><li><strong>读取机密性</strong>：读取受 ACL 限制，但系统目录、安装目录和显式 <code>--read</code> 根仍可读；不隐藏其他进程。</li><li><strong>域级网络白名单</strong>：网络只有 <code>deny</code> 与 <code>open</code> 两种；<code>open</code> 允许任意出网。</li><li><strong>完整回滚</strong>：非 git 任务的 shell 删除不保证可恢复；git worktree 依靠 checkpoint 与逐轮快照。</li><li><strong>绝对安全</strong>：字符串命令策略只降低误操作概率，不是安全边界。</li></ul><h2 id="_2-模式" tabindex="-1">2. 模式 <a class="header-anchor" href="#_2-模式" aria-label="Permalink to &quot;2. 模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>含义</th><th>执行方式</th></tr></thead><tbody><tr><td><code>read-only</code></td><td>禁止写入/删除工作区</td><td>AppContainer；workspace 只给 <code>(OI)(CI)RX</code>，temp 仍可写</td></tr><tr><td><code>workspace-write</code></td><td>只允许任务工作区 + 私有 temp + 显式写根写入/删除</td><td>AppContainer；workspace 给 <code>(OI)(CI)M</code>，额外写根逐个 <code>--write</code></td></tr><tr><td><code>danger-full-access</code></td><td>不包装</td><td>仅 operator 显式配置或 <code>approvalMode=full</code>；模型不能自行请求</td></tr></tbody></table><p><code>danger-full-access</code> 不是“完全权限”的同义词。完全权限（<code>approvalMode=full</code>）只表示工具审批自动通过；沙箱模式独立计算，并在 full 下明确降级。</p><h2 id="_3-架构" tabindex="-1">3. 架构 <a class="header-anchor" href="#_3-架构" aria-label="Permalink to &quot;3. 架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>native-executor</span></span>
<span class="line"><span>  -&gt; resolveSandboxPolicy()            # workspace / outDir / temp / read roots</span></span>
<span class="line"><span>  -&gt; AgentToolContext.sandbox          # SandboxRuntime { provider, policy }</span></span>
<span class="line"><span>  -&gt; shell-session.confine(exact argv)</span></span>
<span class="line"><span>  -&gt; WindowsNativeSandboxProvider      # 只构造 argv 契约与探测</span></span>
<span class="line"><span>  -&gt; hearth-native.exe sandbox|pty ... # AppContainer、ACL、Job、watchdog</span></span></code></pre></div><p><code>resolveSandboxPolicy</code> 的 <code>workspaceRoot</code> 以任务实际可写的共同根为准：worktree 与 <code>outDir</code> 分离时取二者最近公共祖先（且必须在 <code>HEARTH_ROOT</code> 内）；否则回退到项目根。<code>tempRoot</code> 固定放在 <code>LOCALAPPDATA\\Temp\\hearth-sandbox\\&lt;taskId&gt;</code>（Windows），与 workspace 不相交。</p><p>helper 的四个子命令：</p><ul><li><code>sandbox</code>：创建或复用 AppContainer package SID；只给 workspace、私有 temp、显式 <code>--read</code> / <code>--write</code> 根授权；用 <code>PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES</code> 在 AppContainer 中启动子进程；子进程加入 <code>JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE</code> 的 Job Object；父进程 watchdog 每 500ms 检查 <code>--parent-pid</code>，父死即 <code>TerminateJobObject</code>。</li><li><code>pty</code>：与 <code>sandbox</code> 相同的 AppContainer、ACL 和 Job 约束，但通过 <code>CreatePseudoConsole</code> 分配交互式控制台；stdin/stdout 是 ConPTY 原始字节流。</li><li><code>process-info</code>：返回 PID 与进程创建时间，供宿主租约和后台进程注册表判断 PID 复用。</li><li><code>lease</code>：<code>Global\\Hearth.Host.&lt;name&gt;</code> named mutex，用于单实例宿主租约。</li></ul><p>网络：<code>--network deny</code> 不申请 <code>internetClient</code> capability，子进程没有网络身份；<code>--network open</code> 申请该 capability 并写审计与 proof。任务声明 <code>networkHosts</code> 且不是 <code>open</code> 时，provider 直接 fail-closed，不会给一个“没有网络”的假沙箱。</p><p>child env 采用白名单：保留 <code>PATH</code>/<code>SystemRoot</code> 等启动变量，过滤 <code>*_API_KEY</code>、<code>TOKEN</code>、<code>SECRET</code>、<code>PASSWORD</code>、<code>HEARTH_*</code>、<code>NODE_OPTIONS</code>、<code>PYTHONPATH</code>、<code>LD_PRELOAD</code>、<code>DYLD_INSERT_LIBRARIES</code>、<code>GIT_SSH_COMMAND</code>、<code>BASH_ENV</code> 等；<code>TMP</code>/<code>TEMP</code> 指向私有 temp，包管理器 cache 指向 workspace 内 <code>.hearth/sandbox/cache</code>。</p><h2 id="_4-失败语义" tabindex="-1">4. 失败语义 <a class="header-anchor" href="#_4-失败语义" aria-label="Permalink to &quot;4. 失败语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>行为</th></tr></thead><tbody><tr><td><code>SANDBOX_UNAVAILABLE</code></td><td>不 spawn；任务失败，写审计与 <code>sandbox.unavailable</code></td></tr><tr><td><code>SANDBOX_UNSUPPORTED_POLICY</code></td><td>不 spawn；提示缩小范围或移除域级白名单</td></tr><tr><td>runner failure（<code>sandbox-error:</code> / exit 127）</td><td>归类沙箱故障，不和命令失败混淆</td></tr><tr><td><code>Access is denied</code> / <code>EPERM</code> / <code>EACCES</code></td><td>归类沙箱拒绝，保留 stderr，工具结果带 <code>SANDBOX_DENIED</code> 标记</td></tr></tbody></table><h2 id="_5-测试" tabindex="-1">5. 测试 <a class="header-anchor" href="#_5-测试" aria-label="Permalink to &quot;5. 测试&quot;">​</a></h2><p>当前已覆盖（<code>apps/server/src/windows-native-sandbox.test.ts</code>，12 项）：</p><ul><li>workspace 内写入成功，workspace 外写入被拒绝且文件不存在；</li><li><code>read-only</code> 模式拒绝 workspace 写入；</li><li>junction 指向工作区外时不能逃逸；</li><li>子进程环境过滤模型密钥与其他敏感变量；</li><li>默认网络拒绝，<code>open</code> 才能出网；</li><li>helper 关闭时 Job Object 杀死子进程；</li><li>ConPTY 交互式命令可执行，argv 契约稳定；</li><li>probe 与 helper 缺失的 fail-closed 路径。</li></ul><p>全量 <code>npm test</code> 与 <code>npm run typecheck</code> 也覆盖沙箱与审批的组合路径。</p><h2 id="_6-已知边界" tabindex="-1">6. 已知边界 <a class="header-anchor" href="#_6-已知边界" aria-label="Permalink to &quot;6. 已知边界&quot;">​</a></h2><ul><li>Windows AppContainer 是 <code>partial</code>：读取、网络和进程可见性都不是强隔离；硬链接可 alias；其他 AppContainer 工具 ACL 过的树可能不可读。</li><li>workspace 根会留下 standing ACE（跨 session 复用缓存）；只应在 task worktree 上使用，非 git 项目需显式提示。</li><li>需要 caller-owned 目录；OneDrive、网络共享或企业策略目录可能失败。</li><li>非 git 项目的 <code>shell</code> 删除没有文件历史覆盖；不承诺完整回滚。</li><li>worktree 与 task <code>outDir</code> 分属 <code>.hearth/workspaces</code> 下两个兄弟目录时，共同根是 <code>.hearth/workspaces</code>，shell 理论上可写同级其他任务目录；这是为同时覆盖 worktree 与 out 做的折中。</li><li><code>open</code> 网络模式没有域级 allowlist，也不能限制 raw socket；需要强网络隔离时应使用外部容器或代理。</li><li>PTY 会话不跨宿主重启恢复；重启时统一标记 <code>lost</code> 并清理孤儿进程树。</li></ul>`,27)])])}const b=o(c,[["render",n]]);export{u as __pageData,b as default};
